유효하지 않은 입력은 에러 메시지를 출력합니다.
*/
void fsm_update(fsm_t *fsm, int input) {
    // Example: 0 = idle, 1 = run, 2 = stop
    if (input >= 0 && input < STATE_MAX) {
        fsm->state = (fsm_state_t)input;
        fsm->state_table[fsm->state]();
    } else {
        printf("Invalid input: %d\n", input);
    }
}

