void tl_fsm_update(traffic_light_fsm_t *fsm) {
    if (--fsm->timer <= 0) {
        switch (fsm->state) {
            case TL_RED:
                fsm->state = TL_GREEN;
                fsm->timer = fsm->green_time;
                break;
            case TL_GREEN:
                fsm->state = TL_YELLOW;
                fsm->timer = fsm->yellow_time;
                break;
            case TL_YELLOW:
                fsm->state = TL_RED;
                fsm->timer = fsm->red_time;
                break;
            default:
                fsm->state = TL_RED;
                fsm->timer = fsm->red_time;
                break;
        }
    }
}

