#include <stdint.h>
#include <stdio.h>
#include <assert.h>
#include <string.h>

// ZigZag 인코딩: 음수→양수 매핑
static uint64_t zigzag_encode(int64_t value) {
    return (uint64_t)((value << 1) ^ (value >> 63));
}

// ZigZag 디코딩: 양수→원래 부호
static int64_t zigzag_decode(uint64_t value) {
    return (int64_t)((value >> 1) ^ (~(value & 1) + 1));
}

// Base-128 Varint 인코딩
int encode_zigzag_varint(int64_t value, uint8_t* out) {
    uint64_t uval = zigzag_encode(value);
    int i = 0;
    do {
        uint8_t byte = uval & 0x7F;
        uval >>= 7;
        if (uval != 0) byte |= 0x80;
        out[i++] = byte;
    } while (uval != 0);
    return i;
}

// Base-128 Varint 디코딩
int decode_zigzag_varint(const uint8_t* in, int64_t* value) {
    uint64_t result = 0;
    int shift = 0;
    int i = 0;
    while (1) {
        uint8_t byte = in[i];
        result |= ((uint64_t)(byte & 0x7F)) << shift;
        if ((byte & 0x80) == 0) break;
        shift += 7;
        i++;
    }
    *value = zigzag_decode(result);
    return i + 1;
}

// 테스트 코드

