#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <assert.h>
#include <string.h>

// CRC16-CCITT(0x1021), no reflection, no final XOR
uint16_t crc16_ccitt(const uint8_t* data, size_t len, uint16_t crc_init) {
    uint16_t crc = crc_init;
    for (size_t i = 0; i < len; ++i) {
        crc ^= ((uint16_t)data[i]) << 8;
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x8000)
                crc = (crc << 1) ^ 0x1021;
            else
                crc <<= 1;
        }
    }
    return crc;
}

