#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

#define FRAME_MAX_LEN 256

typedef void (*frame_callback_t)(const uint8_t* frame, size_t len, void* user);

typedef enum {
    FP_IDLE,
    FP_IN_FRAME,
    FP_ESC
} fp_state_t;

typedef struct frame_parser {
    frame_callback_t cb;
    void* user;
    uint8_t buf[FRAME_MAX_LEN];
    size_t pos;
    fp_state_t state;
} frame_parser_t;

frame_parser_t* frame_parser_create(frame_callback_t cb, void* user) {
    if (!cb) return NULL;
    frame_parser_t* p = (frame_parser_t*)malloc(sizeof(frame_parser_t));
    if (!p) return NULL;
    p->cb = cb;
    p->user = user;
    p->pos = 0;
    p->state = FP_IDLE;
    return p;
}

void frame_parser_destroy(frame_parser_t* parser) {
    if (parser) free(parser);
}

void frame_parser_reset(frame_parser_t* parser) {
    if (!parser) return;
    parser->pos = 0;
    parser->state = FP_IDLE;
}

void frame_parser_feed(frame_parser_t* parser, const uint8_t* data, size_t len) {
    if (!parser || !data) return;
    for (size_t i = 0; i < len; ++i) {
        uint8_t b = data[i];
        switch (parser->state) {
            case FP_IDLE:
                if (b == 0x7E) {
                    parser->pos = 0;
                    parser->state = FP_IN_FRAME;
                }
                break;
            case FP_IN_FRAME:
                if (b == 0x7E) {
                    // 프레임 종료
                    if (parser->pos > 0) {
                        parser->cb(parser->buf, parser->pos, parser->user);
                    }
                    parser->pos = 0;
                    // 다음 프레임 시작
                    parser->state = FP_IN_FRAME;
                } else if (b == 0x7D) {
                    parser->state = FP_ESC;
                } else {
                    if (parser->pos < FRAME_MAX_LEN) {
                        parser->buf[parser->pos++] = b;
                    } else {
                        // 오버런: 프레임 무시, 상태 리셋
                        parser->pos = 0;
                        parser->state = FP_IDLE;
                    }
                }
                break;
            case FP_ESC:
                if (b == 0x5E) b = 0x7E;
                else if (b == 0x5D) b = 0x7D;
                // else: 잘못된 이스케이프, 그대로 저장(혹은 오류 복구)
                if (parser->pos < FRAME_MAX_LEN) {
                    parser->buf[parser->pos++] = b;
                    parser->state = FP_IN_FRAME;
                } else {
                    parser->pos = 0;
                    parser->state = FP_IDLE;
                }
                break;
        }
    }
}

