#include <stdio.h>
#include <string.h>
#define false (0)
#define true (1)

int isStringPalindrome(const char *str) {
    if (str == NULL) {
        return false;
    }
    int len = strlen(str);
    if (len == 0) {
        return true;
    }
    int i = 0;
    int j = len - 1;
    while (i < j) {

        if (str[i] != str[j]) {
            return false;
        }
        i++;
        j--;
    }
    return true;
}

int isIntegerPalindrome(int num)
{
    if (num < 0) {
        return false;
    }

    if (num < 10) {
        return true;
    }

    int originNum = num;
    int reversed = 0;

    while (num > 0)
    {
        reversed = reversed * 10 + num % 10;
        num = num / 10;
    }

    return originNum == reversed;
}

